    if semantic.is_available(base) {
        return Name::new(base);
    }

    let mut index = 0;
    loop {
        let candidate = format!("{base}_{index}");
        if semantic.is_available(&candidate) {
            return Name::new(candidate);
        }
        index += 1;
    }
