/// 1. Insert the exception argument into a variable assignment before the
///    `raise` statement. The variable name is `msg`, unless `msg` is already
///    bound in the current scope, in which case a non-colliding name (`msg_0`,
///    `msg_1`, and so on) is used instead.
/// 2. Replace the exception argument with the variable name.
fn generate_fix(
    semantic: &SemanticModel,
    stmt: &Stmt,
    exc_arg: &Expr,
    stmt_indentation: &str,
    stylist: &Stylist,
    locator: &Locator,
) -> Fix {
    let name = message_variable_name(semantic);
    Fix::unsafe_edits(
        Edit::insertion(
            if locator.contains_line_break(exc_arg.range()) {
                format!(
                    "{name} = ({line_ending}{stmt_indentation}{indentation}{}{line_ending}{stmt_indentation}){line_ending}{stmt_indentation}",
