                    locator.slice(exc_arg.range()),
                    stylist.line_ending().as_str(),
                    stmt_indentation,
                )
            },
            stmt.start(),
        ),
        [Edit::range_replacement(name, exc_arg.range())],
    )
}

/// Return the variable name to bind the extracted exception message to.
///
/// Prefer `msg`, but fall back to `msg_0`, `msg_1`, and so on if `msg` (or a
/// preceding candidate) is already bound in the current scope, to avoid
/// shadowing an existing binding.
fn message_variable_name(semantic: &SemanticModel) -> String {
    if semantic.is_available("msg") {
        return "msg".to_string();
    }
    (0..)
        .map(|index| format!("msg_{index}"))
